#[cfg(unix)]
#[allow(clippy::verbose_bit_mask)]
const fn unix_mode_is_private(mode: u32) -> bool {
    // Spell the permission contract as a mask: this is security policy over
    // group/other bits, not a numeric trailing-zero optimization.
    mode & 0o077 == 0
}

